function validateADT1Srn(adt1Srn) {

    var adt1SrnValue = adt1Srn;
    if (adt1SrnValue == null || adt1SrnValue == "") {
        erroronSRN();
    }
    else if (adt1Srn == "Z99999999") {
        gn2orz9case();
    }
    else {

        debugger;
        //ADT1SRN
        var csrfTokenVal = window.parent.document.querySelector("#csrfToken").value;
        const formdata = new FormData();
        var requestData = "{\"requestBody\": {\"action\": \"" + "viewformadt1" + "\" , \"referenceNumber\": \"" + "" + "\"  , \"srNumber\": \"" + adt1Srn + "\"  }}";

        formdata.append("data", encrypt(requestData));
        formdata.append("csrfToken", encrypt(csrfTokenVal));
        formdata.append("method", "post");
        formdata.append("endpointID", "adt1_onload");
        formdata.append("csrfDecode", false);
        const settings1 = {
            "async": false,
            "crossDomain": true,
            "url": "/bin/commongetapi",
            "method": "POST",
            "headers": {},
            "processData": false,
            "contentType": false,
            "mimeType": "multipart/form-data",
            "data": formdata
        };

        $.ajax(settings1).done(function (response) {
            try {

                if (JSON.parse(response).resCode == 200) {
                    var JSONData = JSON.parse(JSON.parse(response).resStr);
                    if (JSONData && JSONData.data == undefined) {
                        onload23B(adt1SrnValue);
                    }
                    else if (JSONData && JSONData.data !== null && JSONData.message.toLowerCase() == "data fetched successfully") {
                        try {
                            guideBridge.resolveNode("gnl2SRNCheck").resetData();
                        } catch (error) {
                            console.error("Error to set a value specific to AOC-4 when GNL-2 SRN is entered");
                        }
                        let shouldPrefill = true;
                        var ogToDate; 
                        var formCIN;
                        if (guideBridge.resolveNode("formName").value == 'AOC-4 CFS') {
                            ogToDate = guideBridge.resolveNode("financialYearDateTo").value;
                            formCIN = guideBridge.resolveNode("CIN_Number_Professional_User").value;

                        }
                        else if (guideBridge.resolveNode("formName").value == 'AOC-4 CFS NBFC') {
                            ogToDate = guideBridge.resolveNode("financialStatsTo").value;
                            formCIN = guideBridge.resolveNode("CIN_Number_Professional_User").value;
                        }
                        else if (guideBridge.resolveNode("formName").value == 'AOC-4'){
                            ogToDate = guideBridge.resolveNode("toDate").value;
							formCIN = guideBridge.resolveNode("savedCinVal").value ? guideBridge.resolveNode("savedCinVal").value : guideBridge.resolveNode("CINofCompany").value ? guideBridge.resolveNode("CINofCompany").value :guideBridge.resolveNode("CIN_Number_Other_User").value ;

                        }
                        else{
							ogToDate = guideBridge.resolveNode("toDate").value;
                            formCIN = guideBridge.resolveNode("savedCinVal").value ? guideBridge.resolveNode("savedCinVal").value : guideBridge.resolveNode("corporateIdentityNumber").value ? guideBridge.resolveNode("corporateIdentityNumber").value :guideBridge.resolveNode("CIN_Number_Other_User").value ;

                        }
                        if (JSONData.data.CIN !== formCIN) {
                            // guideBridge.resolveNode("SRNOfFormADT1")._triggerEvent(guidelib.event.GuideModelEvent.ERROR_CHANGED, "validationStatus", false, "Entered SRN in not valid, Please refer to the ‘?’ icon tooltip for additional error details");
                            guideBridge.resolveNode("SRNOfFormADT1").validateExpMessage = "Entered SRN in not valid, Please refer to the ‘?’ icon tooltip for additional error details"
                            shouldPrefill = false;
                        } else if (JSONData.data.formData.ListAud[0]) {
                            var Listauditor = JSONData.data.formData.CountAud;

                            for (i = 0; i < Listauditor; i++) {
                                var parFromDate = JSONData.data.formData.ListAud[i].PeriodFrom;
                                var parToDate = JSONData.data.formData.ListAud[i].PeriodTo;
                               // var ogToDate = guideBridge.resolveNode("toDate").value || guideBridge.resolveNode("financialYearDateTo").value || guideBridge.resolveNode("toDate").value || guideBridge.resolveNode("financialStatsTo").value;
                                const ok = checkDate(parFromDate, parToDate, ogToDate);
                                if (!ok) {
                                    shouldPrefill = false;
                                    break;
                                }

                            }
                        }
                        if (shouldPrefill) {
                             guideBridge.resolveNode("SRNOfFormADT1").validateExpMessage = "";
                            prefillAdt1Srn(JSONData);
                        }
                    }
                }

                else if (JSON.parse(response).resCode == 500)
                    onload23B(adt1SrnValue);


            } catch (err) {
                console.error(err);
            }
        });


    }
}



