function enableAuditorPanelFields(instCount) {
    try {
        var adPanel = guideBridge.resolveNode("auditors_detail_panel").instanceManager.instances;
        for (i = 0; i < instCount; i++) {
            adPanel[i].incomeTaxOfAuditor.enabled = true;
            adPanel[i].categoryOfAuditor.enabled = true;
            adPanel[i].membershipNumberOfAuditor.enabled = true;
            adPanel[i].nameOfTheAuditor.enabled = true;
            adPanel[i].addressLine1_Auditor.enabled = true;
            adPanel[i].addressLine2_Auditor.enabled = true;
            adPanel[i].pinCode_Auditor.enabled = true;
            adPanel[i].area_locality_Auditor.visible = true;
            if (adPanel[i].area_locality_Auditor == "") {
                adPanel[i].area_locality_Auditor.resetData();

            }

            adPanel[i].area_locality_Auditor.enabled = true;
            adPanel[i].country_Auditor.value = "India";
        }

    } catch (err) {
        console.error("error in enabling fields for instance ", instCount, " and error is -> ", err);
    }

}



