function repeatAuditorPanel(numberOfAuditorsForWhichPanelIsRepeated) {
    try {
        if (numberOfAuditorsForWhichPanelIsRepeated !== "" || numberOfAuditorsForWhichPanelIsRepeated !== null || numberOfAuditorsForWhichPanelIsRepeated !== "null" || numberOfAuditorsForWhichPanelIsRepeated !== undefined) {

            if (guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount < numberOfAuditorsForWhichPanelIsRepeated) {
                var instCount = guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount;
                if (numberOfAuditorsForWhichPanelIsRepeated > 15) {
                    while (instCount < 15) {
                        auditors_detail_panel.instanceManager.addInstance();
                        instCount = guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount;

                    }
                }
                if (numberOfAuditorsForWhichPanelIsRepeated <= 15 && numberOfAuditorsForWhichPanelIsRepeated > 0) {
                    while (instCount < numberOfAuditorsForWhichPanelIsRepeated) {
                        guideBridge.resolveNode("auditors_detail_panel").instanceManager.addInstance();
                        instCount = guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount;
                    }
                }

                if (guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount > numberOfAuditorsForWhichPanelIsRepeated && numberOfAuditorsForWhichPanelIsRepeated > 1) {
                    while (guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount > numberOfAuditorsForWhichPanelIsRepeated) {
                        guideBridge.resolveNode("auditors_detail_panel").instanceManager.removeInstance(guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount - 1);
                    }
                }
            }
            else {
                while (guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount > numberOfAuditorsForWhichPanelIsRepeated && numberOfAuditorsForWhichPanelIsRepeated > 1) {
                    guideBridge.resolveNode("auditors_detail_panel").instanceManager.removeInstance(guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount - 1);
                }
            }
        }

        else {
            while (guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount > 1) {
                guideBridge.resolveNode("auditors_detail_panel").instanceManager.removeInstance(guideBridge.resolveNode("auditors_detail_panel").instanceManager.instanceCount - 1);
            }
        }
    } catch (err) {
        console.error("Error in repeating auditor panel -> ", err);
    }

}

function checkDate(date1, date2, endDate) {
    /* if(!(date1 || date2 || endDate)){
       return false;
     }*/
    const periodForm = new Date(date1);
    const periodTo = new Date(date2);
    const financialEndDate = new Date(endDate);

    periodForm.setHours(0, 0, 0, 0);
    periodTo.setHours(0, 0, 0, 0);
    financialEndDate.setHours(0, 0, 0, 0);

    if (financialEndDate >= periodForm && financialEndDate <= periodTo) {
        guideBridge.resolveNode("SRNOfFormADT1")._triggerEvent(guidelib.event.GuideModelEvent.ERROR_CHANGED, "validationStatus", true, "");
        return true;
    } else {
        //  guideBridge.resolveNode("SRNOfFormADT1")._triggerEvent(guidelib.event.GuideModelEvent.ERROR_CHANGED, "validationStatus", false, "Entered SRN in not valid, Please refer to the ‘?’ icon tooltip for additional error details");
        guideBridge.resolveNode("SRNOfFormADT1").validateExpMessage = "Entered SRN in not valid, Please refer to the ‘?’ icon tooltip for additional error details"
        return false;
    }
}
