var cachedServerTime = "";
 
function getServerTime() {
    try {
        if(cachedServerTime){
            return cachedServerTime;
        }
        var serverTime;
        $.ajax({
            url: '/bin/mca/GetCurrentTime',
            type: 'GET',
            async: false,
            success: function (response) {
                serverTime = response;
                cachedServerTime = serverTime;
            }
        });
      var myArray = serverTime.split(" ");
var srvTime = myArray[0];
 
var srvTimeArray=srvTime.split("/"); 
var mm=srvTimeArray[0]; 
var dd=srvTimeArray[1]; 
var yyyy=srvTimeArray[2]; 
      var srvDate=yyyy+"-"+ mm +"-"+dd;
        return srvDate;
    }
    catch (e) {
        console.error('Error from getServerTime() function :: \n', e.stack);
    }
}

function getGNL1dateOnload(cin,srn) {
 
		const form1956common = new FormData();
		var csrfTokenVal = window.parent.document.querySelector("#csrfToken").value;
		var agmExtendedDate = "";		
		var dataStr = JSON.stringify({
						CIN: cin,
						SRN: srn    
					});       
		form1956common.append("data",encrypt(dataStr) );
		form1956common.append("endpointID", "GET_GNL1_DETAILS");
		form1956common.append("csrfToken", encrypt(csrfTokenVal));
    	form1956common.append("csrfDecode", false);
		const settings = {
			"async": false,
			"crossDomain": true,
			"url": "/bin/commongetapi",
			"method": "POST",
			"headers": {},
			"processData": false,
			"contentType": false,
			"mimeType": "multipart/form-data",
			"data": form1956common
		};

		$.ajax(settings).done(function (response) {
			try {
				var JSONData = JSON.parse(JSON.parse(response).resStr);
				if (JSONData && JSONData.data !== null && JSONData.message.toLowerCase() == "data fetched successfully" && JSONData.data[0].SRType == 'GNL-1') {
                 if (JSONData.data[0].AGMExtendedDate)
                   {
                     agmExtendedDate =  (JSONData.data[0].AGMExtendedDate).replace(/(\d\d)\/(\d\d)\/(\d{4})/, "$3-$2-$1");                  
                   }
				}
			}
			catch(err){
				console.error(err);
			}
		});
		
		return agmExtendedDate;
}
